    targets: [
        .executableTarget(
            name: "Safo",
            dependencies: [
                .product(name: "MarkdownUI", package: "swift-markdown-ui"),
                .product(name: "Splash", package: "Splash"),
            ]
        ),
        .executableTarget(
            name: "safo-cli"
        ),
    ]
)

