 3→struct SidebarView: View {
 4→    @ObservedObject var viewModel: DocumentViewModel
 5→
 6→    var body: some View {
 7→        List {
 8→            if let listing = viewModel.directoryListing {
 9→                let grouped = groupedFiles(listing: listing)
10→
11→                if !grouped.rootFiles.isEmpty {
12→                    ForEach(grouped.rootFiles, id: \.self) { url in
13→                        fileRow(url: url, listing: listing)
14→                    }
15→                }
16→
17→                ForEach(grouped.folders, id: \.name) { folder in
18→                    Section(folder.name) {
19→                        ForEach(folder.files, id: \.self) { url in
20→                            fileRow(url: url, listing: listing)
21→                        }
22→                    }
23→                }
24→            }
25→        }
26→        .listStyle(.sidebar)
27→        .frame(minWidth: Tokens.Layout.sidebarWidth, idealWidth: Tokens.Layout.sidebarWidth)
28→        .scrollContentBackground(.hidden)
29→        .background(Tokens.Colors.sidebarBackground)
30→    }
31→
32→    private func fileRow(url: URL, listing: DirectoryListing) -> some View {
33→        let isCurrent = url == listing.currentFile
34→
35→        return Button {
36→            viewModel.navigateTo(url: url)
37→        } label: {
38→            Text(url.lastPathComponent)
39→                .font(.system(size: Tokens.Typography.sidebarSize))
40→                .foregroundStyle(isCurrent ? Tokens.Colors.accent : Tokens.Colors.textPrimary)
41→                .frame(maxWidth: .infinity, alignment: .leading)
42→        }
43→        .buttonStyle(.plain)
44→        .listRowBackground(
45→            isCurrent ? Tokens.Colors.selectionBackground : Color.clear
46→        )
47→    }
48→}
49→
50→// MARK: - File grouping
51→
52→private extension SidebarView {
53→    struct FolderGroup: Equatable {
54→        let name: String
55→        let files: [URL]
56→    }
57→
58→    struct GroupedFiles {
59→        let rootFiles: [URL]
60→        let folders: [FolderGroup]
61→    }
62→
63→    func groupedFiles(listing: DirectoryListing) -> GroupedFiles {
64→        var rootFiles: [URL] = []
65→        var folderMap: [String: [URL]] = [:]
66→
67→        let rootPath = listing.rootURL.path
68→
69→        for file in listing.files {
70→            let filePath = file.path
71→            let relativePath: String
72→            if filePath.hasPrefix(rootPath) {
73→                let stripped = String(filePath.dropFirst(rootPath.count))
74→                relativePath = stripped.hasPrefix("/") ? String(stripped.dropFirst()) : stripped
75→            } else {
76→                relativePath = file.lastPathComponent
77→            }
78→            let components = relativePath.split(separator: "/")
79→
80→            if components.count == 1 {
81→                rootFiles.append(file)
82→            } else {
83→                let folderName = String(components[0])
84→                folderMap[folderName, default: []].append(file)
85→            }
86→        }
87→
88→        let folders = folderMap.keys.sorted().map { name in
89→            FolderGroup(name: name, files: folderMap[name] ?? [])
90→        }
91→
92→        return GroupedFiles(rootFiles: rootFiles, folders: folders)
93→    }
94→}
