 1→import SwiftUI
 2→
 3→@main
 4→struct SafoApp: App {
 5→    @NSApplicationDelegateAdaptor(AppDelegate.self) var appDelegate
 6→    @StateObject private var viewModel = DocumentViewModel()
 7→
 8→    var body: some Scene {
 9→        WindowGroup {
10→            ContentView(viewModel: viewModel)
11→                .onOpenURL { url in
12→                    handleOpenURL(url)
13→                }
14→                .task {
15→                    openFromLaunchArguments()
16→                }
17→        }
18→        .handlesExternalEvents(matching: Set(arrayLiteral: "*"))
19→        .commands {
20→            CommandGroup(replacing: .newItem) {}
21→            CommandGroup(after: .sidebar) {
22→                Button("Toggle Sidebar") {
23→                    viewModel.toggleSidebar()
24→                }
25→                .keyboardShortcut("s", modifiers: [.command, .shift])
26→            }
27→        }
28→    }
29→
30→    private func handleOpenURL(_ url: URL) {
31→        guard let components = URLComponents(url: url, resolvingAgainstBaseURL: false),
32→              let path = components.queryItems?.first(where: { $0.name == "path" })?.value
33→        else { return }
34→
35→        let fileURL = URL(fileURLWithPath: path)
36→        viewModel.open(url: fileURL)
37→    }
38→
39→    private func openFromLaunchArguments() {
40→        let args = CommandLine.arguments
41→        guard args.count > 1 else { return }
42→
